/// Bundled char n-gram language detector (spec 034 US3).
///
/// Pure Dart, no I/O: the profiles are compile-time constants generated by
/// `tool/gen_langid_profiles.dart` into `profiles_data.dart`. Only the
/// Latin-script languages are modelled — CJK text is decided by
/// `detectLanguage`'s ideograph rule before this ever runs, so a zh profile
/// would be dead weight.
library;

import 'profiles_data.dart';

/// The detector's answer: [language] is the profile's winner and
/// [confidence] a 0..1 margin over the runner-up — how much the winner won
/// by, relative to its own score. `detectLanguage` (`lib/language.dart`)
/// trusts the model only at or above [kLangIdThreshold]; below it the rule
/// table answers instead.
class LangIdResult {
  const LangIdResult(this.language, this.confidence);

  /// Winning language code (`'en'` or `'es'` — the only profiled languages).
  final String language;

  /// Margin over the runner-up, 0..1. 0 means a coin flip (or no evidence).
  final double confidence;
}

/// Below this confidence `detectLanguage` falls back to its rule table.
/// Tuned on held-out sentences (`test/langid_test.dart`) against the
/// rule table's deliberate conservatism: "No, no, no." and "La la land."
/// are English made of words Spanish shares and must stay English, so the
/// gate sits above their ~0.19–0.24 margins; real sentences — accent-less
/// Spanish included — clear 0.27.
const double kLangIdThreshold = 0.25;

/// Normalize exactly as the generator did: lowercase, whitespace collapsed,
/// padded with a space on both sides so boundary n-grams match training.
String _normalize(String text) =>
    ' ${text.toLowerCase().replaceAll(RegExp(r'\s+'), ' ').trim()} ';

/// True when the text holds at least one Latin letter — the only script the
/// profiles cover. Anything else (CJK handled earlier, but also kana,
/// Cyrillic, digits-only) has no evidence to score.
final RegExp _latinLetter = RegExp('[a-záéíóúüñ]');

/// Score [text] against every profiled language and return the winner.
///
/// The score is the summed log10 probability (scaled ×1000, negative) of
/// every char n-gram (1–4) of the normalized text; an unseen n-gram scores
/// the per-(language, n) floor. Longer texts accumulate more evidence, so
/// confidence is the winner's margin *relative* to its own total — a
/// length-independent measure.
LangIdResult detectWithModel(String text) {
  final trimmed = text.trim();
  // Too little text for a stable margin — and the relative-confidence
  // ratio degenerates on a handful of n-grams. The rule table's word
  // lists own short inputs ("hola", "gracias" decide there).
  if (trimmed.length < 8) return const LangIdResult('en', 0);
  final normalized = _normalize(trimmed);
  if (!_latinLetter.hasMatch(normalized)) {
    return const LangIdResult('en', 0);
  }

  var bestLanguage = 'en';
  var bestScore = double.negativeInfinity;
  var secondScore = double.negativeInfinity;

  for (final entry in kLangIdProfiles.entries) {
    final lang = entry.key;
    var score = 0;
    for (var n = 1; n <= 4; n++) {
      final grams = entry.value[n]!;
      final floor = kLangIdFloors[lang]![n]!;
      for (var i = 0; i + n <= normalized.length; i++) {
        score += grams[normalized.substring(i, i + n)] ?? floor;
      }
    }
    final s = score.toDouble();
    if (s > bestScore) {
      secondScore = bestScore;
      bestScore = s;
      bestLanguage = lang;
    } else if (s > secondScore) {
      secondScore = s;
    }
  }

  // Margin over the runner-up, relative to the winner's magnitude. Both
  // scores are negative; a decisive winner leaves the loser far behind.
  final confidence = bestScore < 0 && secondScore < 0
      ? ((bestScore - secondScore) / -bestScore).clamp(0.0, 1.0)
      : 0.0;
  return LangIdResult(bestLanguage, confidence);
}
